import java.util.*;

class Solution {
  public int[] resultsArray(int[][] queries, int k) {
    PriorityQueue<Integer> farthest = new PriorityQueue<>(Collections.reverseOrder());
    int[] answer = new int[queries.length];
    for (int i = 0; i < queries.length; i++) {
      int distance = Math.abs(queries[i][0]) + Math.abs(queries[i][1]);
      farthest.offer(distance);
      if (farthest.size() > k) farthest.poll();
      answer[i] = farthest.size() == k ? farthest.peek() : -1;
    }
    return answer;
  }
}
